// Check full transform chain for WateringCup
var root = GameObject.Find("WateringCup");
if(root!=null){
    Debug.Log("ROOT WateringCup: localPos="+root.transform.localPosition+" localRot="+root.transform.localEulerAngles+" localScale="+root.transform.localScale+" worldPos="+root.transform.position);
    foreach(Transform child in root.transform){
        Debug.Log("  CHILD "+child.name+": localPos="+child.localPosition+" localScale="+child.localScale+" worldPos="+child.position);
        foreach(Transform gc in child){
            Debug.Log("    GC "+gc.name+": localPos="+gc.localPosition+" worldPos="+gc.position);
        }
    }
}
